INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (102301, 2, "アヤネ", 24001, 2, "2020/07/31 12:00:00", 401, 0.0, 0.0, 24, 10046, "やったね、ぷうきち！\nこれならお兄ちゃんたちの\nお手本になれたよね！", 0.0, "2030/12/17 14:59:59");
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (102301, 1, "アヤネ", 24002, 2, "2020/07/31 12:00:00", 402, 0.0, 2.21, 24, 10046, "私たちの勝ちだね！\nぷうきちと一緒なら\nどんなボールでも\nホームランを打ってみせるよ！", 0.0, "2030/12/17 14:59:59");
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (102301, 2, "アヤネ", 24003, 2, "2020/07/31 12:00:00", 403, 0.0, 0.0, 24, 10046, "やったやったぁ！\nお兄ちゃん、見ててくれた？\n私、すっごくがんばったよ！", 0.0, "2030/12/17 14:59:59");
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (192201, 2, "アサヒ", 24004, 1, "2020/07/31 12:00:00", 701, 0.0, 1.99, 24, 10046, "特訓の成果が出たみたいだ！\nもっと練習を重ねて\nこの調子で上達していこう！", 0.0, "2030/12/17 14:59:59");
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (192201, 1, "アサヒ", 24005, 2, "2020/07/31 12:00:00", 702, 0.0, 2.21, 24, 10046, "よし、いい感じだ！\nキャプテンとしての仕事は\nきっちり果たせそうだよ", 0.0, "2030/12/17 14:59:59");
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (192201, 2, "アサヒ", 24006, 1, "2020/07/31 12:00:00", 703, 0.0, 3.33, 24, 10046, "試合に向けて\nいい感覚を掴めた気がするよ！\nこのまま一気に全国大会だ！", 0.0, "2030/12/17 14:59:59");
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (192301, 2, "部員３", 24007, 2, "2020/07/31 12:00:00", 801, 0.0, 0.0, 24, 10046, "このくらい余裕だ\nオレたちは全国大会を\n目指してるんだからな", 0.0, "2030/12/17 14:59:59");
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (192301, 1, "部員３", 24008, 2, "2020/07/31 12:00:00", 802, 0.0, 2.68, 24, 10046, "オレだって\nビーチベースボール選手だ\nどんな球だろうが\n全部スタンドまで飛ばしてやる", 0.0, "2030/12/17 14:59:59");
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (192301, 2, "部員３", 24009, 2, "2020/07/31 12:00:00", 803, 0.0, 0.0, 24, 10046, "いい感じだ\nこれなら試合でも活躍できそうだ\n大暴れしてやる！", 0.0, "2030/12/17 14:59:59");
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (192501, 1, "", 24010, 1, "2020/07/31 12:00:00", 501, 0.0, 0.0, 24, 10046, "やった！", 0.0, "2030/12/17 14:59:59");
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (192501, 1, "", 24011, 1, "2020/07/31 12:00:00", 502, 0.0, 0.0, 24, 10046, "勝ったよ！", 0.0, "2030/12/17 14:59:59");
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (192501, 1, "", 24012, 1, "2020/07/31 12:00:00", 503, 0.0, 0.0, 24, 10046, "いい調子！", 0.0, "2030/12/17 14:59:59");
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (113501, 6, "ミサト", 24013, 2, "2020/07/31 12:00:00", 111, 0.0, 5.33, 24, 10046, "あら～…もしかして\n勝っちゃったのかしら？\nみんなの練習を見ていたから\nかもしれないわね", 0.0, "2030/12/17 14:59:59");
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (113501, 1, "ミサト", 24014, 2, "2020/07/31 12:00:00", 112, 0.0, 6.85, 24, 10046, "みんなの力になりたくて\n先生も頑張ってみました～！\nうまく投げられたみたいで\nよかったわ～！", 0.0, "2030/12/17 14:59:59");
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (113501, 1, "ミサト", 24015, 2, "2020/07/31 12:00:00", 113, 0.0, 3.0, 24, 10046, "練習お疲れさま～！\n先生も協力できて\nとってもうれしいわ～♪\n次も頑張りましょうね～！", 0.0, "2030/12/17 14:59:59");
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (192401, 1, "ダイチ", 24016, 2, "2020/07/31 12:00:00", 611, 0.0, 6.11, 24, 10046, "まだ練習が足りねえみてえだな\nこれっぽっちも本気で\n投げてねえっつーの\nもう一回やんぞ！", 0.0, "2030/12/17 14:59:59");
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (192401, 1, "ダイチ", 24017, 2, "2020/07/31 12:00:00", 612, 0.0, 6.75, 24, 10046, "ふん、当然の結果だな\n俺の球は、誰にも打てねえよ！\nまたやりてえっつーなら\nとことん付き合ってやるぜ！", 0.0, "2030/12/17 14:59:59");
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (192401, 2, "ダイチ", 24018, 2, "2020/07/31 12:00:00", 613, 0.0, 0.0, 24, 10046, "おっしゃあ！\nこの勢いで全国に行ってやるぜ！\n全員三振で仕留めてやる！", 0.0, "2030/12/17 14:59:59");
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (113401, 2, "ハツネ", 24019, 1, "2020/07/31 12:00:00", 211, 0.0, 4.52, 24, 10046, "きらーん☆\nハツネちゃんの大勝利なのだ～！\nみんながもっと上達できるように\n私もまだまだ頑張るからね！", 0.0, "2030/12/17 14:59:59");
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (113401, 2, "ハツネ", 24020, 1, "2020/07/31 12:00:00", 212, 0.0, 3.89, 24, 10046, "やったあ！　私の勝ちだね！\nチアリーダーもピッチャーも\nハツネちゃんに任せてよ！", 0.0, "2030/12/17 14:59:59");
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (113401, 1, "ハツネ", 24021, 2, "2020/07/31 12:00:00", 213, 0.0, 13.49, 24, 10046, "よお～し、この調子でもっと\n頑張ろう…と思ったけど\n超能力を使ったから…\n眠くなってきちゃった…すやぁ…", 0.0, "2030/12/17 14:59:59");
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (106501, 1, "カヤ", 24022, 2, "2020/07/31 12:00:00", 311, 0.0, 3.17, 24, 10046, "いい勝負だったぜ！\nたぎっちまって\nつい本気で投げちまったよ", 0.0, "2030/12/17 14:59:59");
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (106501, 1, "カヤ", 24023, 2, "2020/07/31 12:00:00", 312, 0.0, 4.42, 24, 10046, "どうだ？\nオレ様のボールは熱かっただろ！\nま、でもおまえらの根性も\nなかなかのもんだったぜ", 0.0, "2030/12/17 14:59:59");
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (106501, 6, "カヤ", 24024, 1, "2020/07/31 12:00:00", 313, 0.0, 2.89, 24, 10046, "なんだよ、そんなもんか？\nこっちはまだまだ投げたりねえ\nもっと勝負しようぜ！", 0.0, "2030/12/17 14:59:59");
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (102301, 4, "アヤネ", 24025, 3, "2020/07/31 12:00:00", 421, 0.0, 3.71, 24, 10046, "あとちょっとだったのに～！\n次こそぷうきちと一緒に\n勝ってみせるからね！", 0.0, "2030/12/17 14:59:59");
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (192201, 2, "アサヒ", 24026, 1, "2020/07/31 12:00:00", 721, 0.0, 5.1, 24, 10046, "いい勝負だったね！\nでも、やっぱり悔しいな…\nもっと練習して\n今度は絶対に俺が勝つから！", 0.0, "2030/12/17 14:59:59");
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (192301, 1, "部員３", 24027, 3, "2020/07/31 12:00:00", 821, 0.0, 4.34, 24, 10046, "ちっ…あと一歩足りなかったか\n次こそは絶対に勝つから\nそのつもりでいろ", 0.0, "2030/12/17 14:59:59");
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (192501, 1, "", 24028, 1, "2020/07/31 12:00:00", 521, 0.0, 0.0, 24, 10046, "いい勝負だったよ\nまたやろうね", 0.0, "2030/12/17 14:59:59");
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (113501, 1, "ミサト", 24029, 2, "2020/07/31 12:00:00", 101, 0.0, 5.62, 24, 10046, "とってもよくできました～♪\n頑張ってくれて先生うれしいわ\nこれからも試合に向けて\n練習していきましょうね～", -360.0, "2030/12/17 14:59:59");
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (113501, 1, "ミサト", 24030, 2, "2020/07/31 12:00:00", 102, 0.0, 9.58, 24, 10046, "頑張った成果ね～！\nこのまま練習を続ければ\nもっとすごい成績を残せそうよ\n期待してますからね～！", -360.0, "2030/12/17 14:59:59");
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (113501, 2, "ミサト", 24031, 2, "2020/07/31 12:00:00", 103, 0.0, 0.0, 24, 10046, "いい子、いい子～♪\n頑張り屋さんのあなたを\nたっくさん褒めてあげますからね", -360.0, "2030/12/17 14:59:59");
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (113501, 2, "ミサト", 24032, 1, "2020/07/31 12:00:00", 104, 0.0, 9.13, 24, 10046, "夢に向けて、一歩前進できたわね\nこの調子で、夢を叶えましょう\n目指せ、全国大会～！", -360.0, "2030/12/17 14:59:59");
INSERT INTO `v1_f19e1b2cb05ff78cee95de4f3ef94fc0488911293dd9d71586f83eb7343b12a4` VALUES (113501, 1, "ミサト", 24033, 2, "2020/07/31 12:00:00", 105, 0.0, 8.27, 24, 10046, "絶好調ね～♪\nきっと試合でも大活躍\n間違いなしだわ\n楽しみにしていますからね～！", -360.0, "2030/12/17 14:59:59");
